  _normalizeFileObject(fileName) {
    if (!fileName) return "";
    return fileName.startsWith("/") ? fileName : `/${fileName}`;
  }
  _buildFlatFileSqlBody(fileName, columnDelimiter = ",") {
    const tableName = `tblname_${Date.now()}`;
    const fileObject = this._normalizeFileObject(fileName);
    const connectionProperties = [
      { key: "TypeDetectionScheme", value: "None" },
      { key: "FMT", value: columnDelimiter },
      { key: "SkipTop", value: 0 },
      { key: "RowDelimiter", value: "\n" },
      { key: "QuoteEscapeCharacter", value: '"' },
      { key: "NullValues", value: "NaN" },
      { key: "PushEmptyValuesAsNull", value: true },
      { key: "TrimSpaces", value: true },
      { key: "IncludeColumnHeaders", value: true },
      { key: "AggregateFiles", value: false }
    ];
    const body = {
      source: "File",
      properties: {
        sql: `select *
                      from ${tableName}`,
        tableName,
        fileObject,
        isParameterizedPath: false,
        singleFile: true,
        fileType: "Delimited",
        characterSet: "UTF-8",
        connectionProperties
      },
      parameterId: "",
      parameterName: "",
      sampleRows: 0
    };
    return { body, connectionProperties, tableName, fileObject };
  }
  async _submitFileSchema(workspaceId, accountId, xmlSchema, connectionProperties, subObjectId = "SourceDataset") {
    await this.auth.ensureAuthenticated();
    const boundary = `----FormBoundary${Date.now()}`;
    const infoJson = JSON.stringify({
      objectId: "",
      subObjectId,
      schemaType: "XMLv2",
      schemaInfo: { properties: connectionProperties }
    });
    const multipartBody = [
      `--${boundary}`,
      `Content-Disposition: form-data; name="info"; filename="blob"`,
      `Content-Type: application/json`,
      ``,
      infoJson,
      `--${boundary}`,
      `Content-Disposition: form-data; name="fileSchema"`,
      ``,
      typeof xmlSchema === "string" ? xmlSchema : JSON.stringify(xmlSchema),
      `--${boundary}--`,
      ``
    ].join("\r\n");
    return this.client.icedqRequest(`/api/v1/internal/file-schema`, {
      method: "POST",
      headers: {
        "Content-Type": `multipart/form-data; boundary=${boundary}`,
        "Accept": "application/json, text/plain, */*",
        "Workspace-Id": workspaceId,
        "account-id": accountId || this.client.config.orgId || ""
      },
      body: multipartBody
    }, this.auth.accessToken, this.auth.orgId);
  }
  /**
   * Update an existing file schema (PUT request)
   * @param {string} workspaceId - Workspace ID
   * @param {string} accountId - Account ID
   * @param {string} ruleId - Rule ID (objectId)
   * @param {string} fileSchemaId - Existing file schema ID to update
   * @param {string|Object} xmlSchema - XML schema content
   * @param {Array} connectionProperties - Connection properties array
   * @returns {Promise<Object>} Updated schema response
   */
  async _updateFileSchema(workspaceId, accountId, ruleId, fileSchemaId, xmlSchema, connectionProperties, subObjectId = "SourceDataset") {
    await this.auth.ensureAuthenticated();
    const boundary = `----FormBoundary${Date.now()}`;
    const infoJson = JSON.stringify({
      id: fileSchemaId,
      objectId: ruleId,
      subObjectId,
      schemaType: "XMLv2",
      schemaInfo: { properties: connectionProperties }
    });
    const multipartBody = [
      `--${boundary}`,
      `Content-Disposition: form-data; name="info"; filename="blob"`,
      `Content-Type: application/json`,
      ``,
      infoJson,
      `--${boundary}`,
      `Content-Disposition: form-data; name="fileSchema"`,
      ``,
      typeof xmlSchema === "string" ? xmlSchema : JSON.stringify(xmlSchema),
      `--${boundary}--`,
      ``
    ].join("\r\n");
    return this.client.icedqRequest(`/api/v1/file-schema/${fileSchemaId}`, {
      method: "PUT",
      headers: {
        "Content-Type": `multipart/form-data; boundary=${boundary}`,
        "Accept": "application/json, text/plain, */*",
        "Workspace-Id": workspaceId,
        "account-id": accountId || this.client.config.orgId || ""
      },
      body: multipartBody
    }, this.auth.accessToken, this.auth.orgId);
  }
  /**
   * Submit a rule to iceDQ (POST for create, PUT for update)
   * @param {string} workspaceId - Workspace ID
   * @param {string} folderId - Folder ID where rule should be created
   * @param {Object} rulePayload - Complete rule payload object
   * @param {string} method - HTTP method ('POST' for create, 'PUT' for update)
   * @param {string} ruleId - Rule ID (required for PUT operations)
   * @returns {Promise<Object>} Created/updated rule response
   */
  async _submitRule(workspaceId, folderId, rulePayload, method = "POST", ruleId = null) {
    await this.auth.ensureAuthenticated();
    if (method === "PUT" && !ruleId) {
      throw new McpError("ruleId is required for PUT operations");
    }
    const endpoint = method === "PUT" ? `/api/v1/internal/rules/${ruleId}` : "/api/v1/internal/rules";
    return this.client.icedqRequest(endpoint, {
      method,
      headers: {
        "Content-Type": "application/json",
        "Accept": "application/json, text/plain, */*",
        "Workspace-Id": workspaceId,
        "folder-id": folderId
      },
      body: rulePayload
    }, this.auth.accessToken, this.auth.orgId);
  }
