var GuidanceService = class {
  constructor() {
    this.cache = {};
    this._loadAll();
  }
  _loadAll() {
    for (const topic of Object.keys(TOPIC_METADATA)) {
      try {
        const filePath = join3(GUIDANCE_DIR, `${topic}.md`);
        this.cache[topic] = readFileSync(filePath, "utf-8");
      } catch (error2) {
        log2("warn", `Failed to load guidance topic: ${topic}`, { error: error2.message });
        this.cache[topic] = `Guidance content for '${topic}' is not available.`;
      }
    }
    log2("info", `Loaded ${Object.keys(this.cache).length} guidance topics`);
  }
  getGuidance(topic) {
    const metadata = TOPIC_METADATA[topic];
    if (!metadata) {
      return {
        error: `Unknown topic '${topic}'.`,
        availableTopics: Object.keys(TOPIC_METADATA)
      };
    }
    return {
      topic,
      title: metadata.title,
      content: this.cache[topic],
      relatedTools: metadata.relatedTools,
      relatedTopics: metadata.relatedTopics
    };
  }
};

